#include <Aevrynd/MeshProcessing3D.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <iostream>
#include <limits>
#include <vector>

using namespace Aevrynd;

static Mesh3D Grid(unsigned side){Mesh3D mesh;for(unsigned z=0;z<=side;++z)for(unsigned x=0;x<=side;++x){const float u=float(x)/side,v=float(z)/side,height=.08f*std::sin(u*6.2831853f)*std::sin(v*6.2831853f);mesh.vertices.push_back({u*4-2,height,v*4-2,PackNormalSnorm8({0,1,0},.35f+.5f*u),PackColorRgba8({u,v,1-u,1}),u,v});}const unsigned stride=side+1;for(unsigned z=0;z<side;++z)for(unsigned x=0;x<side;++x){const uint32_t a=z*stride+x,b=a+1,c=a+stride,d=c+1;mesh.indices.insert(mesh.indices.end(),{a,c,b,b,c,d});}return mesh;}
static float OrientationY(const Mesh3D& mesh,size_t offset){const Vec3 a{mesh.vertices[mesh.indices[offset]].x,mesh.vertices[mesh.indices[offset]].y,mesh.vertices[mesh.indices[offset]].z},b{mesh.vertices[mesh.indices[offset+1]].x,mesh.vertices[mesh.indices[offset+1]].y,mesh.vertices[mesh.indices[offset+1]].z},c{mesh.vertices[mesh.indices[offset+2]].x,mesh.vertices[mesh.indices[offset+2]].y,mesh.vertices[mesh.indices[offset+2]].z};return Cross(b-a,c-a).y;}
static std::array<uint32_t,3> Triangle(const Mesh3D& mesh,size_t offset){return{mesh.indices[offset],mesh.indices[offset+1],mesh.indices[offset+2]};}
static bool SameVertex(const Vertex3D& left,const Vertex3D& right){return left.x==right.x&&left.y==right.y&&left.z==right.z&&left.normal==right.normal&&left.color==right.color&&left.u==right.u&&left.v==right.v;}
static bool SameMesh(const Mesh3D& left,const Mesh3D& right){if(left.vertices.size()!=right.vertices.size()||left.indices!=right.indices)return false;for(size_t index=0;index<left.vertices.size();++index)if(!SameVertex(left.vertices[index],right.vertices[index]))return false;return true;}
static bool SameMeshChain(const std::vector<Mesh3D>& left,const std::vector<Mesh3D>& right){if(left.size()!=right.size())return false;for(size_t level=0;level<left.size();++level)if(!SameMesh(left[level],right[level]))return false;return true;}
static bool InsideBounds(const Mesh3D& mesh,const MeshBounds3D& bounds){const Vec3 minimum=bounds.center-bounds.extents,maximum=bounds.center+bounds.extents;for(const Vertex3D& vertex:mesh.vertices)if(vertex.x<minimum.x-.001f||vertex.x>maximum.x+.001f||vertex.y<minimum.y-.001f||vertex.y>maximum.y+.001f||vertex.z<minimum.z-.001f||vertex.z>maximum.z+.001f)return false;return true;}
static size_t CacheMisses(const Mesh3D& mesh,size_t cacheSize){std::vector<uint32_t> cache;size_t misses{};for(uint32_t index:mesh.indices){const auto found=std::find(cache.begin(),cache.end(),index);if(found==cache.end())++misses;else cache.erase(found);cache.insert(cache.begin(),index);if(cache.size()>cacheSize)cache.pop_back();}return misses;}
static Mesh3D SeamGrid(){Mesh3D mesh;constexpr unsigned Side=8;for(unsigned panel=0;panel<2;++panel){const uint32_t base=uint32_t(mesh.vertices.size());for(unsigned z=0;z<=Side;++z)for(unsigned x=0;x<=Side;++x){const float u=float(x)/Side,worldX=panel?u:-1.f+u,worldZ=float(z)/Side;const float worldY=panel?u*.5f:0.f;const Vec3 normal=panel?Normalize(Vec3{-.5f,1,0}):Vec3{0,1,0};mesh.vertices.push_back({worldX,worldY,worldZ,PackNormalSnorm8(normal,1),0xffffffffu,u,worldZ});}const unsigned stride=Side+1;for(unsigned z=0;z<Side;++z)for(unsigned x=0;x<Side;++x){const uint32_t a=base+z*stride+x,b=a+1,c=a+stride,d=c+1;mesh.indices.insert(mesh.indices.end(),{a,c,b,b,c,d});}}return mesh;}

int main(){
    const Mesh3D grid=Grid(24);MeshProcessingError3D error;if(!MeshProcessing3D::Validate(grid,&error)){std::cerr<<"Valid mesh rejected\n";return 1;}
    Mesh3D dirty=grid;dirty.indices.insert(dirty.indices.end(),{0,0,1,0,1,2});Mesh3D cleaned;MeshProcessingStats3D cleanStats;if(!MeshProcessing3D::RemoveDegenerateTriangles(dirty,cleaned,&cleanStats,&error)||cleanStats.removedDegenerateTriangles!=2||cleaned.indices.size()!=grid.indices.size()){std::cerr<<"Degenerate triangle removal failed\n";return 2;}

    Mesh3D duplicated=grid;const uint32_t duplicate=uint32_t(duplicated.vertices.size());duplicated.vertices.push_back(duplicated.vertices[0]);duplicated.indices[0]=duplicate;Mesh3D deduplicated;MeshProcessingStats3D deduplicateStats;if(!MeshProcessing3D::DeduplicateVertices(duplicated,deduplicated,&deduplicateStats,&error)||deduplicateStats.mergedVertices!=1||deduplicated.vertices.size()!=grid.vertices.size()||deduplicated.indices[0]!=0){std::cerr<<"Exact vertex deduplication failed\n";return 3;}

    Mesh3D weightedGrid=grid;weightedGrid.vertices[0].normal=(weightedGrid.vertices[0].normal&0x00ffffffu)|0x80000000u;Mesh3D smooth;if(!MeshProcessing3D::RebuildNormals(weightedGrid,smooth,MeshNormalMode3D::AreaWeightedSmooth,nullptr,&error)){std::cerr<<"Smooth normal rebuild failed\n";return 4;}for(size_t index=0;index<smooth.vertices.size();++index){const Vec4 normal=UnpackNormalSnorm8(smooth.vertices[index].normal);if(normal.y<.9f||(smooth.vertices[index].normal&0xff000000u)!=(weightedGrid.vertices[index].normal&0xff000000u)||smooth.vertices[index].u!=weightedGrid.vertices[index].u||smooth.vertices[index].v!=weightedGrid.vertices[index].v||smooth.vertices[index].color!=weightedGrid.vertices[index].color){std::cerr<<"Smooth normal or vertex attribute preservation failed\n";return 5;}}
    Mesh3D hard;if(!MeshProcessing3D::RebuildNormals(weightedGrid,hard,MeshNormalMode3D::HardEdges,nullptr,&error)||hard.vertices.size()!=weightedGrid.indices.size()){std::cerr<<"Hard-edge normal rebuild failed\n";return 6;}for(size_t offset=0;offset<hard.indices.size();offset+=3){const Vec4 a=UnpackNormalSnorm8(hard.vertices[hard.indices[offset]].normal),b=UnpackNormalSnorm8(hard.vertices[hard.indices[offset+1]].normal),c=UnpackNormalSnorm8(hard.vertices[hard.indices[offset+2]].normal);if(std::abs(a.x-b.x)>.02f||std::abs(a.y-b.y)>.02f||std::abs(a.z-b.z)>.02f||std::abs(a.x-c.x)>.02f||std::abs(a.y-c.y)>.02f||std::abs(a.z-c.z)>.02f){std::cerr<<"Hard-edge face normal mismatch\n";return 7;}for(size_t corner=0;corner<3;++corner)if((hard.vertices[offset+corner].normal&0xff000000u)!=(weightedGrid.vertices[weightedGrid.indices[offset+corner]].normal&0xff000000u)){std::cerr<<"Hard-edge semantic byte changed\n";return 7;}}

    Mesh3D lodInput=grid;lodInput.indices.insert(lodInput.indices.end(),{grid.indices[0],grid.indices[1],grid.indices[2],grid.indices[2],grid.indices[1],grid.indices[0]});Mesh3D lod;MeshProcessingStats3D lodStats;if(!MeshProcessing3D::GenerateLod(lodInput,lod,{.35f,64},&lodStats,&error)||!lod.Valid()||lodStats.outputTriangles>=lodStats.inputTriangles||lodStats.outputTriangles==0){std::cerr<<"Conservative LOD generation failed\n";return 8;}const MeshBounds3D originalBounds=lodInput.Bounds(),lodBounds=lod.Bounds();if(lodBounds.center.x-lodBounds.extents.x<originalBounds.center.x-originalBounds.extents.x-.001f||lodBounds.center.x+lodBounds.extents.x>originalBounds.center.x+originalBounds.extents.x+.001f||lodBounds.center.z-lodBounds.extents.z<originalBounds.center.z-originalBounds.extents.z-.001f||lodBounds.center.z+lodBounds.extents.z>originalBounds.center.z+originalBounds.extents.z+.001f){std::cerr<<"LOD expanded source bounds\n";return 9;}for(size_t offset=0;offset<lod.indices.size();offset+=3)if(OrientationY(lod,offset)<=0){std::cerr<<"LOD winding changed\n";return 10;}std::vector<std::array<uint32_t,3>> lodTriangles;for(size_t offset=0;offset<lod.indices.size();offset+=3){auto triangle=Triangle(lod,offset);std::ranges::sort(triangle);lodTriangles.push_back(triangle);}std::ranges::sort(lodTriangles);if(std::adjacent_find(lodTriangles.begin(),lodTriangles.end())!=lodTriangles.end()){std::cerr<<"LOD duplicate triangle removal failed\n";return 11;}for(const Vertex3D& vertex:lod.vertices)if(!std::isfinite(vertex.u)||!std::isfinite(vertex.v)||!vertex.color||std::none_of(grid.vertices.begin(),grid.vertices.end(),[&](const Vertex3D& source){return(source.normal&0xff000000u)==(vertex.normal&0xff000000u);})){std::cerr<<"LOD vertex attributes invalid\n";return 11;}Mesh3D seamLod;const Mesh3D seam=SeamGrid();if(!MeshProcessing3D::GenerateLod(seam,seamLod,{.55f,16},nullptr,&error)){std::cerr<<"Seam LOD generation failed\n";return 11;}bool lowSeam{},highSeam{},flatNormal{},slopedNormal{};for(const Vertex3D& vertex:seamLod.vertices)if(std::abs(vertex.x)<.0001f){const Vec4 normal=UnpackNormalSnorm8(vertex.normal);lowSeam|=vertex.u<.1f;highSeam|=vertex.u>.9f;flatNormal|=std::abs(normal.x)<.1f;slopedNormal|=normal.x<-.25f;}if(!lowSeam||!highSeam||!flatNormal||!slopedNormal){std::cerr<<"LOD merged UV seam variants\n";return 11;}

    std::vector<Mesh3D> lodChain,lodChainRepeat;MeshLodChainStats3D chainStats;if(!MeshProcessing3D::GenerateLodChain(grid,lodChain,{},&chainStats,&error)||!MeshProcessing3D::GenerateLodChain(grid,lodChainRepeat,{},nullptr,&error)||lodChain.size()!=3||!SameMeshChain(lodChain,lodChainRepeat)||chainStats.generatedLevels!=3||chainStats.sourceTriangles!=grid.indices.size()/3||chainStats.finalTriangles!=lodChain.back().indices.size()/3){std::cerr<<"Deterministic LOD chain generation failed\n";return 11;}size_t previousLodTriangles=grid.indices.size()/3,totalLodTriangles{};const MeshBounds3D sourceBounds=grid.Bounds();for(const Mesh3D& level:lodChain){const size_t levelTriangles=level.indices.size()/3;if(!level.Valid()||levelTriangles>=previousLodTriangles||!InsideBounds(level,sourceBounds)){std::cerr<<"LOD chain topology or bounds failed\n";return 11;}for(size_t offset=0;offset<level.indices.size();offset+=3)if(OrientationY(level,offset)<=0){std::cerr<<"LOD chain winding changed\n";return 11;}previousLodTriangles=levelTriangles;totalLodTriangles+=previousLodTriangles;}if(chainStats.totalOutputTriangles!=totalLodTriangles){std::cerr<<"LOD chain statistics failed\n";return 11;}std::vector<Mesh3D> chainSentinel{Mesh3D::CreateUnitBox()};const std::vector<Mesh3D> originalChainSentinel=chainSentinel;MeshLodChainSettings3D invalidChainSettings;invalidChainSettings.targetTriangleRatios[1]=invalidChainSettings.targetTriangleRatios[0];if(MeshProcessing3D::GenerateLodChain(grid,chainSentinel,invalidChainSettings,nullptr,&error)||error.code!=MeshProcessingErrorCode3D::InvalidSetting||!SameMeshChain(chainSentinel,originalChainSentinel)){std::cerr<<"Invalid LOD chain atomic failure failed\n";return 11;}invalidChainSettings={};invalidChainSettings.maximumTotalOutputTriangles=1;if(MeshProcessing3D::GenerateLodChain(grid,chainSentinel,invalidChainSettings,nullptr,&error)||error.code!=MeshProcessingErrorCode3D::LimitExceeded||!SameMeshChain(chainSentinel,originalChainSentinel)){std::cerr<<"Bounded LOD chain atomic failure failed\n";return 11;}
    MeshLodChainSettings3D sphereChainSettings;sphereChainSettings.targetTriangleRatios={.6f,.3f,.08f};std::vector<Mesh3D> sphereChain;if(!MeshProcessing3D::GenerateLodChain(Mesh3D::CreateUnitSphere(32,20),sphereChain,sphereChainSettings,nullptr,&error)||sphereChain.size()!=3){std::cerr<<"Closed model LOD chain generation failed "<<int(error.code)<<"/"<<error.elementIndex<<"\n";return 11;}

    Mesh3D scrambled=grid;scrambled.indices.clear();const size_t triangleCount=grid.indices.size()/3;for(size_t order=0;order<triangleCount;++order){const size_t triangle=(order*577)%triangleCount;scrambled.indices.insert(scrambled.indices.end(),{grid.indices[triangle*3],grid.indices[triangle*3+1],grid.indices[triangle*3+2]});}Mesh3D reordered;if(!MeshProcessing3D::ReorderForVertexCache(scrambled,reordered,16,nullptr,&error)||reordered.vertices.size()!=scrambled.vertices.size()||reordered.indices.size()!=scrambled.indices.size()){std::cerr<<"Cache reorder failed\n";return 12;}for(size_t index=0;index<scrambled.vertices.size();++index)if(!SameVertex(reordered.vertices[index],scrambled.vertices[index])){std::cerr<<"Cache reorder changed vertex attributes\n";return 12;}std::vector<std::array<uint32_t,3>> beforeTriangles,afterTriangles;for(size_t offset=0;offset<scrambled.indices.size();offset+=3){beforeTriangles.push_back(Triangle(scrambled,offset));afterTriangles.push_back(Triangle(reordered,offset));}std::ranges::sort(beforeTriangles);std::ranges::sort(afterTriangles);if(beforeTriangles!=afterTriangles||CacheMisses(reordered,16)>=CacheMisses(scrambled,16)){std::cerr<<"Cache reorder changed topology or did not improve misses\n";return 13;}

    const Mesh3D originalSentinel=Mesh3D::CreateUnitBox();Mesh3D sentinel=originalSentinel,invalid=grid;invalid.indices[0]=uint32_t(invalid.vertices.size());if(MeshProcessing3D::GenerateLod(invalid,sentinel,{},nullptr,&error)||error.code!=MeshProcessingErrorCode3D::InvalidIndex||!SameMesh(sentinel,originalSentinel)){std::cerr<<"Invalid-index atomic failure failed\n";return 14;}invalid=grid;invalid.vertices[0].x=std::numeric_limits<float>::infinity();if(MeshProcessing3D::RebuildNormals(invalid,sentinel,MeshNormalMode3D::AreaWeightedSmooth,nullptr,&error)||error.code!=MeshProcessingErrorCode3D::NonFiniteVertex||!SameMesh(sentinel,originalSentinel)){std::cerr<<"Non-finite atomic failure failed\n";return 15;}invalid=grid;invalid.vertices[0].x=1000001.f;if(MeshProcessing3D::RemoveDegenerateTriangles(invalid,sentinel,nullptr,&error)||error.code!=MeshProcessingErrorCode3D::NonFiniteVertex||!SameMesh(sentinel,originalSentinel)){std::cerr<<"Huge-coordinate atomic failure failed\n";return 15;}MeshProcessingLimits3D limits;limits.maximumInputVertices=10;if(MeshProcessing3D::DeduplicateVertices(grid,sentinel,nullptr,&error,limits)||error.code!=MeshProcessingErrorCode3D::LimitExceeded||!SameMesh(sentinel,originalSentinel)){std::cerr<<"Bounded-input atomic failure failed\n";return 16;}limits={};limits.maximumScratchBytes=1;if(MeshProcessing3D::ReorderForVertexCache(grid,sentinel,16,nullptr,&error,limits)||error.code!=MeshProcessingErrorCode3D::LimitExceeded||!SameMesh(sentinel,originalSentinel)){std::cerr<<"Scratch-limit atomic failure failed\n";return 16;}Mesh3D signedZero=grid;const uint32_t zeroDuplicate=uint32_t(signedZero.vertices.size());Vertex3D zeroVertex=signedZero.vertices[0];zeroVertex.x=-0.f;zeroVertex.u=-0.f;signedZero.vertices[0].x=0.f;signedZero.vertices[0].u=0.f;signedZero.vertices.push_back(zeroVertex);signedZero.indices[0]=zeroDuplicate;Mesh3D zeroDeduplicated;if(!MeshProcessing3D::DeduplicateVertices(signedZero,zeroDeduplicated,nullptr,&error)||zeroDeduplicated.vertices.size()!=grid.vertices.size()){std::cerr<<"Signed-zero deduplication failed\n";return 16;}Mesh3D alias=duplicated;if(!MeshProcessing3D::DeduplicateVertices(alias,alias,nullptr,&error)||!SameMesh(alias,deduplicated)){std::cerr<<"Aliased output processing failed\n";return 16;}

    std::cout<<"inputTriangles="<<lodStats.inputTriangles<<" lodTriangles="<<lodStats.outputTriangles<<" lodVertices="<<lodStats.outputVertices<<" chainFinalTriangles="<<chainStats.finalTriangles<<" chainTotalTriangles="<<chainStats.totalOutputTriangles<<" merged="<<lodStats.mergedVertices<<" residentState="<<MeshProcessing3D::RetainsMemory<<'\n';return 0;
}
